// Tree Array Representation and Preorder Traversal (Iterative)\n// Array Representation of Tree\n// [10, 20, 30, 40, 50, 60] - level order\n/*\nRoot at index 0\nLeft child of i: 2*i + 1\nRight child of i: 2*i + 2\nParent of i: (i-1)/2\n*/\n\n#include <bits/stdc++.h>\nusing namespace std;\n\nvoid printTree(vector<int>& tree) {\n    for(int i = 0; i < tree.size(); i++) {\n        cout << tree[i] << " ";\n    }\n    cout << endl;\n}\n\nint getParent(vector<int>& tree, int i) {\n    if(i == 0) return tree[0];\n    else return tree[(i-1)/2];\n}\n\nint getLeftChild(vector<int>& tree, int i) {\n    int index = 2*i + 1;\n    if(index >= tree.size()) return 0;\n    else return tree[index];\n}\n\nint getRightChild(vector<int>& tree, int i) {\n    int index = 2*i + 2;\n    if(index >= tree.size()) return 0;\n    else return tree[index];\n}\n\nvoid printChildren(vector<int>& tree, int i) {\n    int index = 2*i + 1;\n    if(index >= tree.size()) {\n        cout << "NOT BOTH CHILD EXIST" << endl;\n    } else {\n        cout << tree[index] << " " << tree[index+1] << endl;\n    }\n}\n\nvoid dfs_pre(vector<int>& tree) {\n    stack<int> st;\n    st.push(0);\n    \n    while(!st.empty()) {\n        int root_index = st.top();\n        st.pop();\n        cout << tree[root_index] << " ";\n        int leftIndex = 2*root_index + 1;\n        int rightIndex = 2*root_index + 2;\n        if(rightIndex < tree.size()) st.push(rightIndex);\n        if(leftIndex < tree.size()) st.push(leftIndex);\n    }\n}\n\nint main() {\n    vector<int> tree = {10, 20, 30, 40, 50, 60};\n    dfs_pre(tree);\n    return 0;\n}